      throw new TypeError('Event must be a string');
    }
    const listeners = this._events.get(event);
    if (!listeners || listeners.length === 0) {
      return false;
    }

    // Snapshot current listeners to decide who to call at start of emit
    // Note: listeners added during emit should not be called until next emit.
    // Listeners removed during emit are still called in the current one (unless once).
    const snapshot = [...listeners];

    for (const reg of snapshot) {
      // Check if reg is still in the active listeners array (or at least valid,
      // wait: "a listener removed during the emit is still called in the current one").
      // But what about once listeners? A once listener should be removed immediately before it runs or marked so it never runs twice.
      if (reg.once) {
        // If it's a once listener, we should remove it from the actual listeners array now (if still present)
        // so it doesn't run twice if triggered recursively.
        const currentListeners = this._events.get(event);
        if (currentListeners) {
          const idx = currentListeners.indexOf(reg);
          if (idx !== -1) {
            currentListeners.splice(idx, 1);
            if (currentListeners.length === 0) {
              this._events.delete(event);
            }
          }
        }
        // Also ensure we only call it once even if invoked multiple times or snapshot has duplicates
        if (reg._calledOnce) {
          continue;
        }
        reg._calledOnce = true;
      }

      reg.listener(...args);
    }

    return true;
  }

