{"action":"write_file","path":"emitter.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { Emitter } = require('./emitter');

test('listeners run in registration order with the arguments', () => {
  const e = new Emitter();
  const seen = [];
  e.on('x', (a, b) => seen.push(['first', a, b]));
  e.on('x', (a) => seen.push(['second', a]));
  assert.equal(e.emit('x', 1, 2), true);
  assert.deepEqual(seen, [['first', 1, 2], ['second', 1]]);
});

test('once runs one time', () => {
  const e = new Emitter();
  let n = 0;
  e.once('x', () => n++);
  e.emit('x');
  e.emit('x');
  assert.equal(n, 1);
});

test('emit reports whether anyone listened', () => {
  assert.equal(new Emitter().emit('nobody'), false);
});

test('unsubscribe function works and can be called multiple times', () => {
  const e = new Emitter();
  let n = 0;
  const unsub = e.on('x', () => n++);
  assert.equal(e.listenerCount('x'), 1);
  unsub();
  unsub();
  assert.equal(e.listenerCount('x'), 0);
  e.emit('x');
  assert.equal(n, 0);
});

test('off removes earliest registration and returns correct boolean', () => {
  const e = new Emitter();
  const fn = () => {};
  e.on('x', fn);
  e.on('x', fn);
  assert.equal(e.listenerCount('x'), 2);
  assert.equal(e.off('y', fn), false);
  assert.equal(e.off('x', () => {}), false);
  assert.equal(e.off('x', fn), true);
  assert.equal(e.listenerCount('x'), 1);
  assert.equal(e.off('x', fn), true);
  assert.equal(e.listenerCount('x'), 0);
  assert.equal(e.off('x', fn), false);
});

test('emit snapshot behavior: added during emit not called, removed during emit still called', () => {
  const e = new Emitter();
  const log = [];
  const fn2 = () => log.push('fn2');
  const unsub1 = e.on('x', () => {
    log.push('fn1');
    unsub1();
    e.on('x', fn2);
  });

  e.emit('x');
  assert.deepEqual(log, ['fn1']);

  e.emit('x');
  assert.deepEqual(log, ['fn1', 'fn2']);
});

test('once listener is removed before called and never runs twice even on re-emit', () => {
  const e = new Emitter();
  let count = 0;
  e.once('x', () => {
    count++;
    e.emit('x');
  });
  e.emit('x');
  assert.equal(count, 1);
});

test('error in listener propagates and stops remaining listeners', () => {
  const e = new Emitter();
  let secondCalled = false;
  e.on('x', () => {
    throw new Error('fail');
  });
  e.on('x', () => {
    secondCalled = true;
  });

  assert.throws(() => {
    e.emit('x');
  }, /fail/);
  assert.equal(secondCalled, false);
});

test('validation checks for event and listener types', () => {
  const e = new Emitter();
  assert.throws(() => e.on(123, () => {}), TypeError);
  assert.throws(() => e.on('x', 'not a fn'), TypeError);
  assert.throws(() => e.once(123, () => {}), TypeError);
  assert.throws(() => e.once('x', null), TypeError);
  assert.throws(() => e.off(123, () => {}), TypeError);
  assert.throws(() => e.off('x', {}), TypeError);
  assert.throws(() => e.emit(123), TypeError);
  assert.throws(() => e.listenerCount(123), TypeError);
});
"}
